//! Replays tests/vectors/patch-vectors.json, generated by running the real
//! `apps/desktop/src/shared/patch.ts` under bun, through both patch
//! implementations (plain values and the revisioned document).

use pm_model::Document;
use pm_model::json::{self, Value, parse};
use pm_model::patch::{
    Patch, PatchErrorKind, PathPart, apply_patches, diff_patches, is_patch_list, patches_from_value,
};

fn vectors() -> Value {
    let text = include_str!("vectors/patch-vectors.json");
    parse(text).expect("vector file parses")
}

/// The committed vectors, plus a larger local file when PM_PATCH_VECTORS names one.
fn all_vectors() -> Vec<Value> {
    let mut out = vec![vectors()];
    if let Ok(path) = std::env::var("PM_PATCH_VECTORS") {
        let text = std::fs::read_to_string(&path).expect("PM_PATCH_VECTORS is readable");
        out.push(parse(&text).expect("PM_PATCH_VECTORS parses"));
    }
    out
}

fn kind_name(kind: PatchErrorKind) -> &'static str {
    match kind {
        PatchErrorKind::TypeError => "TypeError",
        PatchErrorKind::RangeError => "RangeError",
        PatchErrorKind::Limit => "Limit",
        PatchErrorKind::Mismatch => "Mismatch",
    }
}

/// `JSON.stringify` of a JavaScript document equals our canonical text after
/// both are parsed (key order is the only difference).
fn same_json(actual: Option<&Value>, expected: &Value) -> Result<(), String> {
    let expected = match expected {
        Value::Null => None,
        Value::String(text) => Some(parse(&text.to_string_lossy()).map_err(|e| e.to_string())?),
        other => return Err(format!("bad expectation {other:?}")),
    };
    let actual_text = actual.map(json::to_canonical_string);
    let expected_text = expected.as_ref().map(json::to_canonical_string);
    if actual_text == expected_text {
        Ok(())
    } else {
        Err(format!("got {actual_text:?}, want {expected_text:?}"))
    }
}

#[test]
fn every_vector_matches_patch_ts() {
    for vectors in all_vectors() {
        check_cases(vectors.get("cases").unwrap().as_array().unwrap());
    }
}

fn check_cases(cases: &[Value]) {
    assert!(cases.len() > 1000, "expected the generated cases");
    let mut failures = Vec::new();
    for case in cases {
        let name = case.get("name").unwrap().as_str().unwrap().to_owned();
        let doc = match case.get("doc").unwrap() {
            Value::Null => None,
            Value::String(text) => Some(parse(&text.to_string_lossy()).unwrap()),
            _ => panic!("{name}: bad doc"),
        };
        let patches = patches_from_value(case.get("patches").unwrap()).unwrap();
        let expected_error = case.get("error").unwrap().as_object().map(|e| {
            (
                e.get("index").unwrap().as_f64().unwrap() as usize,
                e.get("kind").unwrap().as_str().unwrap().to_owned(),
            )
        });
        let expected_result = case.get("result").unwrap();

        // Plain values.
        let mut root = doc.clone();
        let outcome = apply_patches(&mut root, &patches);
        let error = outcome
            .err()
            .map(|e| (e.index, kind_name(e.kind).to_owned()));
        if error != expected_error {
            failures.push(format!(
                "{name} (values): error {error:?}, want {expected_error:?}"
            ));
            continue;
        }
        if let Err(message) = same_json(root.as_ref(), expected_result) {
            failures.push(format!("{name} (values): {message}"));
        }

        // The revisioned document.
        let mut document = Document::new(doc, 0);
        let outcome = document.apply(&patches);
        let error = outcome
            .err()
            .map(|e| (e.index, kind_name(e.kind).to_owned()));
        if error != expected_error {
            failures.push(format!(
                "{name} (document): error {error:?}, want {expected_error:?}"
            ));
            continue;
        }
        if let Err(message) = same_json(document.to_value().as_ref(), expected_result) {
            failures.push(format!("{name} (document): {message}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures[..failures.len().min(20)].join("\n")
    );
}

#[test]
fn is_patch_list_matches_patch_ts() {
    let vectors = vectors();
    for case in vectors.get("patchLists").unwrap().as_array().unwrap() {
        let value = case.get("value").unwrap();
        let max = case.get("maxBytes").unwrap().as_f64().unwrap() as usize;
        let ok = case.get("ok").unwrap().as_bool().unwrap();
        assert_eq!(
            is_patch_list(value, max),
            ok,
            "{}",
            json::to_canonical_string(value)
        );
    }
}

#[test]
fn negative_zero_index_is_key_zero() {
    let mut root = Some(parse(r#"{"a":[1,2]}"#).unwrap());
    apply_patches(
        &mut root,
        &[Patch::set(
            vec!["a".into(), PathPart::Index(-0.0)],
            Value::from(9),
        )],
    )
    .unwrap();
    assert_eq!(
        json::to_canonical_string(root.as_ref().unwrap()),
        r#"{"a":[9,2]}"#
    );
    // A numeric -0 delete is splice(-0, 1): the first element.
    apply_patches(
        &mut root,
        &[Patch::delete(vec!["a".into(), PathPart::Index(-0.0)])],
    )
    .unwrap();
    assert_eq!(
        json::to_canonical_string(root.as_ref().unwrap()),
        r#"{"a":[2]}"#
    );
}

#[test]
fn nan_and_infinite_indices_coerce_like_javascript() {
    let mut root = Some(parse(r#"{"a":[1,2,3]}"#).unwrap());
    // splice(NaN, 1) removes index 0; the key "NaN" is not an index for sets.
    apply_patches(
        &mut root,
        &[
            Patch::delete(vec!["a".into(), PathPart::Index(f64::NAN)]),
            Patch::set(vec!["a".into(), PathPart::Index(f64::NAN)], Value::from(7)),
            Patch::delete(vec!["a".into(), PathPart::Index(f64::INFINITY)]),
            Patch::delete(vec!["a".into(), PathPart::Index(f64::NEG_INFINITY)]),
        ],
    )
    .unwrap();
    assert_eq!(
        json::to_canonical_string(root.as_ref().unwrap()),
        r#"{"a":[3]}"#
    );
}

#[test]
fn array_growth_is_bounded() {
    let mut root = Some(parse(r#"{"a":[]}"#).unwrap());
    let err = apply_patches(
        &mut root,
        &[Patch::set(
            vec!["a".into(), PathPart::Index(1e9)],
            Value::from(1),
        )],
    )
    .unwrap_err();
    assert_eq!(err.kind, PatchErrorKind::Limit);
    let err = apply_patches(
        &mut root,
        &[Patch::set(
            vec!["a".into(), "length".into()],
            Value::from(4_294_967_295u64),
        )],
    )
    .unwrap_err();
    assert_eq!(err.kind, PatchErrorKind::Limit);
    let err = apply_patches(
        &mut root,
        &[Patch::set(
            vec!["a".into(), "length".into()],
            Value::from(4_294_967_296u64),
        )],
    )
    .unwrap_err();
    assert_eq!(err.kind, PatchErrorKind::RangeError);
}

/// diffPatches' contract: forward turns before into after, backward undoes it,
/// and same-length arrays with stable ids stay leaf-level.
#[test]
fn diff_patches_round_trip() {
    let before = parse(
        r#"{"layers":[{"id":"a","x":1,"p":{"v":0}},{"id":"b","x":2}],"name":"P","gone":true,"arr":[1,2,3]}"#,
    )
    .unwrap();
    let after = parse(
        r#"{"layers":[{"id":"a","x":5,"p":{"v":0}},{"id":"b","x":2}],"name":"Q","new":{"k":-0},"arr":[1,2]}"#,
    )
    .unwrap();
    let (forward, backward) = diff_patches(Some(&before), Some(&after));
    let paths: Vec<String> = forward
        .iter()
        .map(|p| {
            json::to_canonical_string(&Value::Array(
                p.path.iter().map(PathPart::to_value).collect(),
            ))
        })
        .collect();
    assert_eq!(
        paths,
        vec![
            r#"["arr"]"#,
            r#"["gone"]"#,
            r#"["layers",0,"x"]"#,
            r#"["name"]"#,
            r#"["new"]"#
        ]
    );
    let mut root = Some(before.clone());
    apply_patches(&mut root, &forward).unwrap();
    assert_eq!(
        json::to_canonical_string(root.as_ref().unwrap()),
        json::to_canonical_string(&after.json_normalized())
    );
    apply_patches(&mut root, &backward).unwrap();
    assert_eq!(
        json::to_canonical_string(root.as_ref().unwrap()),
        json::to_canonical_string(&before)
    );
    // Reordered ids replace the whole array.
    let reordered = parse(r#"{"layers":[{"id":"b","x":2},{"id":"a","x":1,"p":{"v":0}}]}"#).unwrap();
    let start = parse(r#"{"layers":[{"id":"a","x":1,"p":{"v":0}},{"id":"b","x":2}]}"#).unwrap();
    let (forward, _) = diff_patches(Some(&start), Some(&reordered));
    assert_eq!(forward.len(), 1);
    assert_eq!(forward[0].path, vec![PathPart::from("layers")]);
}
